			function bytesToSize(bytes) {
			    var sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
			    if (bytes == 0) return '0 Byte';
			    var i = parseInt(Math.floor(Math.log(bytes) / Math.log(1024)));
			    return Math.round(bytes / Math.pow(1024, i), 2) + ' ' + sizes[i];
			}

			//파일 다운로드 요청을 보낸다.
			function doDownFile(psFileNm, psAtfino, psMngSn, psServerFileNm) {
			    
			    var locArr = location.href.split("/");
			    var contextPath = "";
			    if (locArr[3] != null && locArr[3] != "" && locArr[3] == "ISRY_BackEnd") {
			        contextPath = "/" + locArr[3];
			    }
			    
			    var loc = contextPath + "/isry/itgcm/sysmgmt/file/fileDownWeb.do" +
			        "?file=" +
			        "&filename=" + encodeURIComponent(psFileNm == null ? "" : psFileNm) +
			        //"&path=" + encodeURIComponent(psSaveFileNm == null ? "" : psSaveFileNm);
			        "&atfino=" + encodeURIComponent(psAtfino == null ? "" : psAtfino) +
			        "&mngSn=" + encodeURIComponent(psMngSn == null ? "" : psMngSn) +
			        "&serverFilename=" + encodeURIComponent(psServerFileNm == null ? "" : psServerFileNm);
			    
			    console.log("헬프 URL", loc);
			    
			    $.ajax({
			            url: loc,
			            data: {},
			            method: "GET",
			            //dataType: "json",
			            cache: false,
			            xhrFields: {
			                responseType: "blob"
			            }
			        })
			        .done(function(data, message, xhr) {
			            //hideAjaxImage(); 
			            if (xhr.readyState == 4 && xhr.status == 200) {
			                // 성공했을때만 파일 다운로드 처리하고
			                var disposition = xhr.getResponseHeader('Content-Disposition');
			                var filename;
			                if (disposition && disposition.indexOf('attachment') !== -1) {
			                    var filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/;
			                    var matches = filenameRegex.exec(disposition);
			                    if (matches != null && matches[1]) filename = matches[1].replace(/['"]/g, '');
			                }
			                var blob = new Blob([data]);
			                var link = document.createElement('a');
			                link.href = window.URL.createObjectURL(blob);
			                link.download = decodeURIComponent(filename);
			                link.click();
			            } else {
			                //실패했을때는 alert 메시지 출력
			                alert("다운로드에 실패하였습니다.");
			            }
			        })
			        .fail(function(xhr, status, errorThrown) {
			            alert("다운로드에 실패하였습니다.");
			          
			        });
			    
			}

